/**
 * Fonts the OG-image route imports `with { type: "bytes" }`. Nitro inlines the
 * file as a `Uint8Array`; TypeScript does not know the attribute yet, so the
 * shape is declared here. Keyed by the route's own specifier rather than
 * `*.ttf`: `vite/client` already declares that one as an asset URL `string`,
 * and the wildcard with the longer fixed prefix is the one TypeScript picks.
 */
declare module "../../og-assets/fonts/*.ttf" {
  const data: Uint8Array;
  export default data;
}

/**
 * `#undocs/og-icon` — the docs project's own `icon.svg` markup, or "" when it
 * has none. Generated by `virtual` in `nitro.config.ts`.
 */
declare module "#undocs/og-icon" {
  const svg: string;
  export default svg;
}
